//! Tests: MSE handshake golden vectors + plain/arc4 dual-mode duplex
//! self-negotiation roundtrip + policy tables + sniffing + fatal input
//! paths. Golden vectors are generated by an independent second
//! implementation (`scripts/gen_mse_vectors.py`: Python hashlib SHA-1 +
//! hand-written RC4) with fixed private keys and zero pad.
//!
use std::time::Duration;

use serde_json::Value;

use super::{
    Arc4, CRYPTO_ARC4, CRYPTO_BITFIELD_LENGTH, CRYPTO_PLAIN_TEXT, CryptoLevel, CryptoPolicy,
    DhKeyExchange, Direction, IA_MAX_LENGTH, KEY_LENGTH, MAX_PAD_LENGTH, MseError, ReceiverParser,
    Sniff, VC_LENGTH, cipher_keys, compose_initiator_step2, compose_receiver_step2, identify,
    initiate, receive, req1_hash, req23_hash,
};

const TIMEOUT: Duration = Duration::from_secs(5);
const IH: [u8; 20] = [0u8; 20];

/// Golden vectors (see the `scripts/gen_mse_vectors.py` header comment and
/// the fixture `_meta`).
fn vectors() -> Value {
    match serde_json::from_str(include_str!("../../tests/fixtures/mse_vectors.json")) {
        Ok(v) => v,
        Err(e) => panic!("mse fixture parse failed: {e}"),
    }
}

fn hex_bytes(s: &str) -> Vec<u8> {
    let b = s.as_bytes();
    if !b.len().is_multiple_of(2) {
        panic!("odd hex length");
    }
    (0..b.len() / 2)
        .map(|i| {
            u8::from_str_radix(&s[2 * i..2 * i + 2], 16).unwrap_or_else(|e| panic!("bad hex: {e}"))
        })
        .collect()
}

fn vec_hex(v: &Value, key: &str) -> Vec<u8> {
    hex_bytes(
        v.get(key)
            .and_then(Value::as_str)
            .unwrap_or_else(|| panic!("missing vector key {key}")),
    )
}

// ---------------------------------------------------------------------------
// Vectors 1-5: ARC4 primitive KATs (source: official IETF RFC 6229 §2 test
// vectors; the offset-1024 entry also anchors the MSE "drop the first
// 1024B of keystream" semantics from MSEHandshake.cc).
// ---------------------------------------------------------------------------

#[test]
fn arc4_rfc6229_kats() {
    let zeros = [0u8; 16];
    // key1 (128-bit) offset 0
    let mut c = Arc4::new(&hex_bytes("0102030405060708090a0b0c0d0e0f10"));
    let mut ks = zeros;
    c.apply(&mut ks);
    assert_eq!(
        hex_bytes("9ac7cc9a609d1ef7b2932899cde41b97"),
        ks,
        "RFC 6229 §2 key1@0"
    );
    // key2 (80-bit) offset 0
    let mut c = Arc4::new(&hex_bytes("0102030405060708090a"));
    ks = zeros;
    c.apply(&mut ks);
    assert_eq!(
        hex_bytes("ede3b04643e586cc907dc21851709902"),
        ks,
        "RFC 6229 §2 key2@0"
    );
    // key3 (40-bit) offset 0
    let mut c = Arc4::new(&hex_bytes("0102030405"));
    ks = zeros;
    c.apply(&mut ks);
    assert_eq!(
        hex_bytes("b2396305f03dc027ccc3524a0a1118a8"),
        ks,
        "RFC 6229 §2 key3@0"
    );
    // key1 offset 256
    let mut c = Arc4::new(&hex_bytes("0102030405060708090a0b0c0d0e0f10"));
    ks = zeros;
    c.discard(256);
    c.apply(&mut ks);
    assert_eq!(
        hex_bytes("d39d566bc6bce3010768151549f3873f"),
        ks,
        "RFC 6229 §2 key1@256"
    );
    // key1 offset 1024 — the keystream anchor after MSE's 1024B ARC4 discard.
    let mut c = Arc4::new(&hex_bytes("0102030405060708090a0b0c0d0e0f10"));
    ks = zeros;
    c.discard(1024);
    c.apply(&mut ks);
    assert_eq!(
        hex_bytes("bdf0324e6083dcc6d3cedd3ca8c53c16"),
        ks,
        "RFC 6229 §2 key1@1024"
    );
}

/// ARC4 self-inverse (two applies with the same key restore the plaintext; MSE in-place semantics).
#[test]
fn arc4_roundtrip_inplace() {
    let mut enc = Arc4::new(b"some-key");
    let mut dec = Arc4::new(b"some-key");
    let mut data: Vec<u8> = (0..1000u32).map(|i| (i % 251) as u8).collect();
    let orig = data.clone();
    enc.apply(&mut data);
    assert_ne!(data[..64], orig[..64]);
    dec.apply(&mut data);
    assert_eq!(data, orig);
}

// ---------------------------------------------------------------------------
// Vectors 6-8: DH-768 (group constants from MSEHandshake.cc; private keys
// and golden values from gen_mse_vectors.py, modpow = g^x mod p; cf.
// LibgmpDHKeyExchange.cc).
// ---------------------------------------------------------------------------

#[test]
fn dh_vectors() {
    let v = vectors();
    // Vector 6: g^1 mod p = 2 (the 96B big-endian fixed-width encoding
    // anchor, left zero-padded).
    let pub1 = DhKeyExchange::from_private_key(&[1u8]).public_key_bytes();
    assert_eq!(vec_hex(&v, "dh_pub_1"), pub1.to_vec(), "g^1 encoding");
    // Vector 7: initiator public key for a fixed 160-bit private key.
    let xi = hex_bytes(
        v.get("_meta")
            .and_then(|m| m.get("x_initiator"))
            .and_then(Value::as_str)
            .unwrap_or_else(|| panic!("missing x_initiator")),
    );
    let pub_i = DhKeyExchange::from_private_key(&xi).public_key_bytes();
    assert_eq!(vec_hex(&v, "dh_pub_initiator"), pub_i.to_vec());
    // Vector 8: both sides derive the same shared secret, matching the golden value.
    let xr = hex_bytes(
        v.get("_meta")
            .and_then(|m| m.get("x_receiver"))
            .and_then(Value::as_str)
            .unwrap_or_else(|| panic!("missing x_receiver")),
    );
    let dh_i = DhKeyExchange::from_private_key(&xi);
    let dh_r = DhKeyExchange::from_private_key(&xr);
    let s_i = dh_i.compute_secret(&dh_r.public_key_bytes());
    let s_r = dh_r.compute_secret(&dh_i.public_key_bytes());
    assert_eq!(s_i, s_r);
    assert_eq!(vec_hex(&v, "secret"), s_i.to_vec(), "shared secret vector");
}

/// Random private keys are 160-bit (MSEHandshake.cc); public keys are 96B fixed-width.
#[test]
fn dh_random_key_shape() {
    let dh = DhKeyExchange::random();
    let pub0 = dh.public_key_bytes();
    assert_eq!(KEY_LENGTH, pub0.len());
    // Exchanging with its own public key is non-zero (a random private key
    // is almost surely non-degenerate).
    let s = dh.compute_secret(&pub0);
    assert!(s.iter().any(|&b| b != 0));
}

// ---------------------------------------------------------------------------
// Vectors 9-11: key derivation (formulas from MSEHandshake.cc; golden
// values from gen_mse_vectors.py's independent hashlib.sha1 implementation).
// ---------------------------------------------------------------------------

#[test]
fn key_derivation_vectors() {
    let v = vectors();
    let secret: [u8; KEY_LENGTH] = vec_hex(&v, "secret")
        .try_into()
        .unwrap_or_else(|_| panic!("bad array length"));
    assert_eq!(vec_hex(&v, "req1"), req1_hash(&secret).to_vec(), "req1");
    assert_eq!(
        vec_hex(&v, "req23"),
        req23_hash(&secret, &IH).to_vec(),
        "req2/req3 xor"
    );
    let (key_a, key_b) = cipher_keys(&secret, &IH, Direction::Initiator);
    assert_eq!(vec_hex(&v, "key_a"), key_a.to_vec(), "keyA");
    assert_eq!(vec_hex(&v, "key_b"), key_b.to_vec(), "keyB");
    // Receive direction: the local/peer key prefixes swap (MSEHandshake.cc).
    let (local_r, peer_r) = cipher_keys(&secret, &IH, Direction::Receiver);
    assert_eq!(key_b.to_vec(), local_r.to_vec());
    assert_eq!(key_a.to_vec(), peer_r.to_vec());
}

// ---------------------------------------------------------------------------
// Vectors 12-13: full step2 stream golden vectors (layouts from
// MSEHandshake.cc initiator/receiver; encoding = gen_mse_vectors.py's
// independent implementation).
// ---------------------------------------------------------------------------

#[test]
fn step2_golden_streams() {
    let v = vectors();
    let secret: [u8; KEY_LENGTH] = vec_hex(&v, "secret")
        .try_into()
        .unwrap_or_else(|_| panic!("bad array length"));
    // Vector 12: initiator step2 = req1||req23||enc(VC+provide(PLAIN|ARC4)+padC=0+IA=0).
    let (local_key, _) = cipher_keys(&secret, &IH, Direction::Initiator);
    let mut enc = super::dropped_arc4(&local_key);
    let provide = CRYPTO_PLAIN_TEXT | CRYPTO_ARC4;
    let step2 = compose_initiator_step2(&secret, &IH, provide, 0, &mut enc);
    assert_eq!(vec_hex(&v, "initiator_stream"), step2, "initiator step2");
    // Vector 13: receiver step2 = enc(VC+select(ARC4)+padD=0).
    // The receiver's local-direction key = keyB (MSEHandshake.cc
    // initiator=false -> "keyB").
    let (key_b, _) = cipher_keys(&secret, &IH, Direction::Receiver);
    let mut enc_r = super::dropped_arc4(&key_b);
    let step2r = compose_receiver_step2(CRYPTO_ARC4, 0, &mut enc_r);
    assert_eq!(vec_hex(&v, "receiver_stream"), step2r, "receiver step2");
}

/// Vector 14: the initiator's VC probe marker = the first 8 bytes of the
/// receiver step2 ciphertext (keystream XOR zero VC; from the MSEHandshake.cc
/// construction + gen_mse_vectors.py). Verified end-to-end through the
/// parser: the golden receiver stream must be consumed without error by the
/// initiator parser.
#[test]
fn initiator_parses_receiver_golden_stream() {
    let v = vectors();
    let key_b: [u8; 20] = vec_hex(&v, "key_b")
        .try_into()
        .unwrap_or_else(|_| panic!("bad array length"));
    let stream = vec_hex(&v, "receiver_stream");
    // The golden VC marker must equal the first 8 bytes of the receiver
    // stream (immediate hit at zero pad).
    assert_eq!(
        vec_hex(&v, "initiator_vc_marker"),
        stream[..VC_LENGTH].to_vec()
    );
    let mut parser = super::InitiatorParser::new(key_b);
    // Feed in chunks (2 bytes each, covering marker boundaries across chunks).
    for chunk in stream.chunks(2) {
        parser
            .push(chunk)
            .unwrap_or_else(|e| panic!("parser rejected golden stream: {e}"));
    }
    assert!(parser.is_done());
    assert_eq!(Some(CRYPTO_ARC4), parser.select(), "select = ARC4 bit");
}

/// Receiver vector: the golden initiator stream is consumed without error
/// by the receiver parser (req1/req23/VC/provide/IA).
#[test]
fn receiver_parses_initiator_golden_stream() {
    let v = vectors();
    let secret: [u8; KEY_LENGTH] = vec_hex(&v, "secret")
        .try_into()
        .unwrap_or_else(|_| panic!("bad array length"));
    let stream = vec_hex(&v, "initiator_stream");
    let mut parser = ReceiverParser::new(vec![IH], secret);
    for chunk in stream.chunks(7) {
        parser
            .push(chunk)
            .unwrap_or_else(|e| panic!("parser rejected golden stream: {e}"));
    }
    assert!(parser.is_done());
    let outcome = parser.outcome().unwrap_or_else(|| panic!("no outcome"));
    assert_eq!(0, outcome.matched);
    assert_eq!(CRYPTO_PLAIN_TEXT | CRYPTO_ARC4, outcome.provide);
    assert!(outcome.ia.is_empty(), "golden IA is zero-length");
}

// ---------------------------------------------------------------------------
// CryptoPolicy tables (semantics from MSEHandshake.cc)
// ---------------------------------------------------------------------------

#[test]
fn crypto_policy_tables() {
    let optional = CryptoPolicy::optional();
    let required = CryptoPolicy {
        require_crypto: true,
        min_level: CryptoLevel::Plain,
    };
    let min_arc4 = CryptoPolicy {
        require_crypto: false,
        min_level: CryptoLevel::Arc4,
    };
    // provide: ARC4 always present; plain only when !require && min==plain.
    assert_eq!(CRYPTO_PLAIN_TEXT | CRYPTO_ARC4, optional.provide());
    assert_eq!(CRYPTO_ARC4, required.provide());
    assert_eq!(CRYPTO_ARC4, min_arc4.provide());
    // Receiver selects from provide: plain offered and allowed -> plain.
    assert_eq!(
        Some(CryptoLevel::Plain),
        optional.select_from_provide(CRYPTO_PLAIN_TEXT | CRYPTO_ARC4)
    );
    // arc4 only -> arc4; with require, plain is offered but not selected.
    assert_eq!(
        Some(CryptoLevel::Arc4),
        optional.select_from_provide(CRYPTO_ARC4)
    );
    assert_eq!(
        Some(CryptoLevel::Arc4),
        required.select_from_provide(CRYPTO_PLAIN_TEXT | CRYPTO_ARC4)
    );
    // plain-only offered and allowed -> plain; a zero bitmap -> None.
    assert_eq!(
        Some(CryptoLevel::Plain),
        optional.select_from_provide(CRYPTO_PLAIN_TEXT)
    );
    assert_eq!(None, optional.select_from_provide(0));
    // Initiator selects from select: the ARC4 bit dominates the plain bit.
    assert_eq!(
        Some(CryptoLevel::Arc4),
        optional.select_from_select(CRYPTO_PLAIN_TEXT | CRYPTO_ARC4)
    );
    assert_eq!(
        Some(CryptoLevel::Plain),
        optional.select_from_select(CRYPTO_PLAIN_TEXT)
    );
    assert_eq!(
        Some(CryptoLevel::Arc4),
        min_arc4.select_from_select(CRYPTO_ARC4)
    );
    assert_eq!(None, min_arc4.select_from_select(CRYPTO_PLAIN_TEXT));
}

// ---------------------------------------------------------------------------
// Sniffing (identifyHandshakeType = MSEHandshake.cc)
// ---------------------------------------------------------------------------

#[test]
fn sniff_boundaries() {
    let pstr = b"BitTorrent protocol";
    // legacy: 0x13 + pstr.
    let mut legacy = vec![19u8];
    legacy.extend_from_slice(pstr);
    assert_eq!(Sniff::Legacy, identify(&legacy, pstr));
    // 0x13 but wrong pstr -> encrypted (only pstr is compared).
    let mut fake = vec![19u8];
    fake.extend_from_slice(b"XitTorrent protocol");
    assert_eq!(Sniff::Encrypted, identify(&fake, pstr));
    // Any MSE stream head (public key) -> encrypted.
    assert_eq!(Sniff::Encrypted, identify(&[0x00; 20], pstr));
    // Under 20B -> NeedMore.
    assert_eq!(Sniff::NeedMore, identify(&legacy[..19], pstr));
    assert_eq!(Sniff::NeedMore, identify(&[], pstr));
}

// ---------------------------------------------------------------------------
// Fatal input paths (verifyPadLength / verifyVC / receiveReceiverIALength /
// marker sync windows in MSEHandshake.cc)
// ---------------------------------------------------------------------------

/// Craft a "req1||req23||enc(payload)" test stream with fixed keys.
fn craft_initiator_stream(secret: &[u8; KEY_LENGTH], payload_tail: &[u8], vc_ok: bool) -> Vec<u8> {
    let (local_key, _) = cipher_keys(secret, &IH, Direction::Initiator);
    let mut enc = super::dropped_arc4(&local_key);
    let mut body = Vec::new();
    body.extend_from_slice(&[0u8; VC_LENGTH]);
    body.extend_from_slice(payload_tail);
    if !vc_ok {
        body[0] ^= 0xff; // corrupt the VC
    }
    enc.apply(&mut body);
    let mut out = req1_hash(secret).to_vec();
    out.extend_from_slice(&req23_hash(secret, &IH));
    out.extend_from_slice(&body);
    out
}

fn test_secret() -> [u8; KEY_LENGTH] {
    DhKeyExchange::from_private_key(&[42u8])
        .compute_secret(&DhKeyExchange::from_private_key(&[7u8]).public_key_bytes())
}

#[test]
fn receiver_rejects_bad_vc() {
    let secret = test_secret();
    let mut tail = [0u8; CRYPTO_BITFIELD_LENGTH].to_vec();
    tail.extend_from_slice(&0u16.to_be_bytes());
    let stream = craft_initiator_stream(&secret, &tail, false);
    let mut parser = ReceiverParser::new(vec![IH], secret);
    match parser.push(&stream) {
        Err(MseError::InvalidVc) => {}
        other => panic!("expected InvalidVc, got {other:?}"),
    }
}

#[test]
fn receiver_rejects_unknown_info_hash() {
    let secret = test_secret();
    let mut tail = [0u8; CRYPTO_BITFIELD_LENGTH].to_vec();
    tail.extend_from_slice(&0u16.to_be_bytes());
    let stream = craft_initiator_stream(&secret, &tail, true);
    // IH not among candidates -> req23 mismatch.
    let other_ih = [9u8; 20];
    let mut parser = ReceiverParser::new(vec![other_ih], secret);
    match parser.push(&stream) {
        Err(MseError::UnknownInfoHash) => {}
        other => panic!("expected UnknownInfoHash, got {other:?}"),
    }
}

#[test]
fn receiver_rejects_pad_over_512() {
    let secret = test_secret();
    let mut tail = [0u8; CRYPTO_BITFIELD_LENGTH].to_vec();
    tail.extend_from_slice(&513u16.to_be_bytes());
    let stream = craft_initiator_stream(&secret, &tail, true);
    let mut parser = ReceiverParser::new(vec![IH], secret);
    match parser.push(&stream) {
        Err(MseError::PadTooLarge {
            pad: "PadC",
            length: 513,
            ..
        }) => {}
        other => panic!("expected PadTooLarge, got {other:?}"),
    }
}

#[test]
fn receiver_rejects_ia_over_68() {
    let secret = test_secret();
    let mut tail = [0u8; CRYPTO_BITFIELD_LENGTH].to_vec();
    tail.extend_from_slice(&0u16.to_be_bytes());
    tail.extend_from_slice(&(IA_MAX_LENGTH as u16 + 1).to_be_bytes());
    let stream = craft_initiator_stream(&secret, &tail, true);
    let mut parser = ReceiverParser::new(vec![IH], secret);
    match parser.push(&stream) {
        Err(MseError::IaTooLarge(69)) => {}
        other => panic!("expected IaTooLarge(69), got {other:?}"),
    }
}

#[test]
fn receiver_ia_payload_decrypted() {
    let secret = test_secret();
    let ia: Vec<u8> = (0..68u8).collect();
    let (local_key, _) = cipher_keys(&secret, &IH, Direction::Initiator);
    let mut enc = super::dropped_arc4(&local_key);
    let mut body = Vec::new();
    body.extend_from_slice(&[0u8; VC_LENGTH]);
    body.extend_from_slice(&[0u8; CRYPTO_BITFIELD_LENGTH]);
    body.extend_from_slice(&0u16.to_be_bytes());
    body.extend_from_slice(&(ia.len() as u16).to_be_bytes());
    body.extend_from_slice(&ia);
    enc.apply(&mut body);
    let mut out = req1_hash(&secret).to_vec();
    out.extend_from_slice(&req23_hash(&secret, &IH));
    out.extend_from_slice(&body);
    let mut parser = ReceiverParser::new(vec![IH], secret);
    parser.push(&out).unwrap_or_else(|e| panic!("push: {e}"));
    assert!(parser.is_done());
    let outcome = parser.outcome().unwrap_or_else(|| panic!("outcome"));
    assert_eq!(ia, outcome.ia, "IA must be decrypted to plaintext");
}

#[test]
fn receiver_marker_sync_window() {
    let secret = test_secret();
    // Marker-free random stream (deterministic fill); buffering past the
    // sync window -> MarkerNotFound.
    let noise: Vec<u8> = (0..1200u32).map(|i| (i % 253) as u8 + 1).collect();
    let mut parser = ReceiverParser::new(vec![IH], secret);
    match parser.push(&noise) {
        Err(MseError::MarkerNotFound { marker: "req1" }) => {}
        other => panic!("expected MarkerNotFound, got {other:?}"),
    }
}

#[test]
fn initiator_marker_sync_window() {
    let (_, peer_key) = cipher_keys(&test_secret(), &IH, Direction::Initiator);
    let noise: Vec<u8> = (0..700u32).map(|i| (i % 251) as u8 + 1).collect();
    let mut parser = super::InitiatorParser::new(peer_key);
    match parser.push(&noise) {
        Err(MseError::MarkerNotFound { marker: "VC" }) => {}
        other => panic!("expected MarkerNotFound, got {other:?}"),
    }
}

/// Non-zero padC/padD lengths are consumed correctly (layout robustness beyond the golden streams).
#[test]
fn receiver_consumes_nonzero_padc() {
    let secret = test_secret();
    // Full step2 layout: VC + provide + len(padC)=300 + padC (all zero,
    // per MSEHandshake.cc) + len(IA)=0 — pad and len(IA) are both encrypted.
    let mut tail = [0u8; CRYPTO_BITFIELD_LENGTH].to_vec();
    tail.extend_from_slice(&300u16.to_be_bytes());
    tail.extend_from_slice(&[0u8; 300]);
    tail.extend_from_slice(&0u16.to_be_bytes());
    let stream = craft_initiator_stream(&secret, &tail, true);
    let mut parser = ReceiverParser::new(vec![IH], secret);
    parser.push(&stream).unwrap_or_else(|e| panic!("push: {e}"));
    assert!(parser.is_done(), "padC must be consumed");
    assert!(
        parser
            .outcome()
            .unwrap_or_else(|| panic!("o"))
            .ia
            .is_empty()
    );
}

// ---------------------------------------------------------------------------
// duplex self-negotiation roundtrip (plain/arc4 dual modes) + Encrypted
// stream transparency to the upper layer.
// ---------------------------------------------------------------------------

async fn negotiate_pair(
    init_policy: CryptoPolicy,
    recv_policy: CryptoPolicy,
) -> (
    super::Encrypted<tokio::io::DuplexStream>,
    super::Encrypted<tokio::io::DuplexStream>,
    CryptoLevel,
) {
    let (a, b) = tokio::io::duplex(8192);
    let ih = IH;
    let init = tokio::spawn(async move { initiate(a, ih, init_policy, TIMEOUT).await });
    let recv = tokio::spawn(async move { receive(b, &[ih], recv_policy, TIMEOUT).await });
    let negotiated_i = init
        .await
        .unwrap_or_else(|e| panic!("initiate join: {e}"))
        .unwrap_or_else(|e| panic!("initiate: {e}"));
    let (negotiated_r, matched) = recv
        .await
        .unwrap_or_else(|e| panic!("receive join: {e}"))
        .unwrap_or_else(|e| panic!("receive: {e}"));
    assert_eq!(0, matched);
    assert_eq!(negotiated_i.crypto, negotiated_r.crypto, "level must agree");
    (
        negotiated_i.stream,
        negotiated_r.stream,
        negotiated_i.crypto,
    )
}

/// Bidirectional duplex data roundtrip (64KiB each way over the negotiated
/// streams; both ends driven concurrently so one task cannot fill the 8KiB
/// duplex buffer and self-deadlock).
async fn duplex_echo(
    mut cli: impl tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + Send + 'static,
    mut srv: impl tokio::io::AsyncRead + tokio::io::AsyncWrite + Unpin + Send + 'static,
) {
    use tokio::io::{AsyncReadExt, AsyncWriteExt};
    let payload: Vec<u8> = (0..65536u32).map(|i| (i % 7 + i / 251) as u8).collect();
    let expect = payload.clone();
    let expect_tx = payload.clone();
    let tx = tokio::spawn(async move {
        cli.write_all(&expect_tx)
            .await
            .unwrap_or_else(|e| panic!("{e}"));
        let mut got2 = vec![0u8; expect_tx.len()];
        cli.read_exact(&mut got2)
            .await
            .unwrap_or_else(|e| panic!("{e}"));
        got2
    });
    let rx = tokio::spawn(async move {
        let mut got = vec![0u8; expect.len()];
        srv.read_exact(&mut got)
            .await
            .unwrap_or_else(|e| panic!("{e}"));
        // Fragmented writes, covering write-path encryption and read-path buffering.
        for chunk in expect.chunks(999) {
            srv.write_all(chunk).await.unwrap_or_else(|e| panic!("{e}"));
        }
        got
    });
    let sent_back = rx.await.unwrap_or_else(|e| panic!("rx join: {e}"));
    let echoed = tx.await.unwrap_or_else(|e| panic!("tx join: {e}"));
    assert_eq!(payload, sent_back, "cli→srv roundtrip");
    assert_eq!(payload, echoed, "srv→cli roundtrip");
}

#[tokio::test]
async fn duplex_negotiate_plain_roundtrip() {
    let (cli, srv, level) =
        negotiate_pair(CryptoPolicy::optional(), CryptoPolicy::optional()).await;
    assert_eq!(
        CryptoLevel::Plain,
        level,
        "optional+optional → plain（cc:447-456）"
    );
    duplex_echo(cli, srv).await;
}

#[tokio::test]
async fn duplex_negotiate_arc4_roundtrip() {
    // Both sides min-level=arc4 -> provide has no plain -> both select arc4
    // (the aria2 MSEHandshakeTest.cc V_ARC4 case).
    let arc4 = CryptoPolicy {
        require_crypto: false,
        min_level: CryptoLevel::Arc4,
    };
    let (cli, srv, level) = negotiate_pair(arc4, arc4).await;
    assert_eq!(CryptoLevel::Arc4, level);
    duplex_echo(cli, srv).await;
}

#[tokio::test]
async fn duplex_require_crypto_forces_arc4() {
    // Initiator require-crypto (provide has no plain) + receiver optional ->
    // arc4; silent fallback to plaintext is explicitly forbidden.
    let required = CryptoPolicy {
        require_crypto: true,
        min_level: CryptoLevel::Plain,
    };
    let (cli, srv, level) = negotiate_pair(required, CryptoPolicy::optional()).await;
    assert_eq!(CryptoLevel::Arc4, level);
    duplex_echo(cli, srv).await;
}

#[tokio::test]
async fn duplex_receiver_min_arc4_forces_arc4() {
    // Initiator min=arc4 (provide is ARC4-only) + receiver require-crypto:
    // the select still contains ARC4 so it succeeds; a receiver whose provide
    // lacks ARC4 is not constructible (ARC4 is always provided) — hence:
    // initiator optional, receiver min=arc4 -> arc4 both ways.
    let recv = CryptoPolicy {
        require_crypto: false,
        min_level: CryptoLevel::Arc4,
    };
    let (cli, srv, level) = negotiate_pair(CryptoPolicy::optional(), recv).await;
    assert_eq!(CryptoLevel::Arc4, level);
    duplex_echo(cli, srv).await;
}

/// MAX_PAD_LENGTH bound shape check: random pad length is generated in 0..=512.
#[test]
fn pad_len_bounds() {
    for _ in 0..200 {
        let n = super::random_pad_len();
        assert!(n <= MAX_PAD_LENGTH, "pad {n} > {MAX_PAD_LENGTH}");
    }
}

// ---------------------------------------------------------------------------
// Encrypted write path: staged-ciphertext retry contract (flush-mode
// buffer validation + inner-writer Ok(0) guard). Regression coverage:
// a mismatched retry buffer used to drain the old ciphertext while the
// new bytes went out unencrypted (permanent ARC4 keystream desync), and
// an inner writer stuck at Ok(0) used to spin the flush loops forever.
// ---------------------------------------------------------------------------

use std::io::ErrorKind;
use std::pin::Pin;
use std::task::{Context, Poll};

use tokio::io::AsyncWrite;

/// Inner writer that accepts at most `accept` bytes per poll and records
/// everything accepted (drives partial writes through `Encrypted`).
struct PartialWriter {
    accept: usize,
    written: Vec<u8>,
}

impl AsyncWrite for PartialWriter {
    fn poll_write(
        mut self: Pin<&mut Self>,
        _cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<std::io::Result<usize>> {
        let n = self.accept.min(buf.len());
        self.written.extend_from_slice(&buf[..n]);
        Poll::Ready(Ok(n))
    }

    fn poll_flush(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Poll::Ready(Ok(()))
    }

    fn poll_shutdown(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Poll::Ready(Ok(()))
    }
}

/// Inner writer that accepts at most `accept` bytes on the first `ok_polls`
/// polls and then reports `Ok(0)` forever (the stalled-writer trigger).
struct StalledWriter {
    accept: usize,
    ok_polls: usize,
    written: Vec<u8>,
}

impl AsyncWrite for StalledWriter {
    fn poll_write(
        mut self: Pin<&mut Self>,
        _cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<std::io::Result<usize>> {
        if self.ok_polls == 0 {
            return Poll::Ready(Ok(0));
        }
        self.ok_polls -= 1;
        let n = self.accept.min(buf.len());
        self.written.extend_from_slice(&buf[..n]);
        Poll::Ready(Ok(n))
    }

    fn poll_flush(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Poll::Ready(Ok(()))
    }

    fn poll_shutdown(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Poll::Ready(Ok(()))
    }
}

/// A waker-backed context for driving poll fns directly (never wakes).
fn poll_cx() -> Context<'static> {
    Context::from_waker(std::task::Waker::noop())
}

/// A retry with a buffer that is not the unaccepted remainder of the
/// staged write must be rejected with `InvalidInput` (the old ciphertext
/// must not drain, and the stream must stay recoverable via the correct
/// remainder with the ARC4 keystream intact).
#[test]
fn encrypted_write_rejects_mismatched_retry_buffer() {
    let key = [7u8; 20];
    let plaintext: Vec<u8> = (0..10u8).collect();

    let mut stream = super::Encrypted::new(
        PartialWriter {
            accept: 4,
            written: Vec::new(),
        },
        Some(Arc4::new(&key)),
        None,
    );

    // First sighting: encrypt once, inner accepts 4/10 -> Ok(4), the
    // ciphertext remainder stays staged.
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &plaintext) {
        Poll::Ready(Ok(4)) => {}
        other => panic!("expected Ok(4) partial write, got {other:?}"),
    }

    // Retry with a different buffer (here the full original length, as a
    // caller ignoring the accepted count would pass) -> InvalidInput.
    let alien = [0xABu8; 10];
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &alien) {
        Poll::Ready(Err(e)) => assert_eq!(ErrorKind::InvalidInput, e.kind()),
        other => panic!("expected InvalidInput, got {other:?}"),
    }
    assert_eq!(
        4,
        stream.get_ref().written.len(),
        "the rejected retry must not write anything"
    );

    // The stream stays usable: the correct remainder drains the staged
    // ciphertext and is accepted fully.
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &plaintext[4..]) {
        Poll::Ready(Ok(6)) => {}
        other => panic!("expected Ok(6) remainder retry, got {other:?}"),
    }

    // The wire bytes are the one-shot ARC4 of the original plaintext
    // (encrypted exactly once; the keystream never desyncs).
    let mut expect = plaintext.clone();
    Arc4::new(&key).apply(&mut expect);
    assert_eq!(expect, stream.get_ref().written, "wire ciphertext");
}

/// A flush-loop retry that meets an inner writer reporting `Ok(0)` must
/// surface `WriteZero` instead of spinning forever.
#[test]
fn encrypted_write_reports_write_zero_on_stalled_inner() {
    let key = [9u8; 20];
    let plaintext: Vec<u8> = (0..10u8).collect();

    let mut stream = super::Encrypted::new(
        StalledWriter {
            accept: 4,
            ok_polls: 1,
            written: Vec::new(),
        },
        Some(Arc4::new(&key)),
        None,
    );

    // First sighting: inner accepts 4/10 -> Ok(4), remainder staged.
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &plaintext) {
        Poll::Ready(Ok(4)) => {}
        other => panic!("expected Ok(4) partial write, got {other:?}"),
    }

    // Correct remainder retry: the flush loop meets the stalled inner
    // writer (Ok(0)) -> WriteZero instead of spinning forever.
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &plaintext[4..]) {
        Poll::Ready(Err(e)) => assert_eq!(ErrorKind::WriteZero, e.kind()),
        other => panic!("expected WriteZero, got {other:?}"),
    }
}

/// `poll_flush` draining the staged ciphertext must report `WriteZero`
/// on a stalled inner writer (same unbounded-loop guard as `poll_write`).
#[test]
fn encrypted_flush_reports_write_zero_on_stalled_inner() {
    let key = [9u8; 20];
    let plaintext: Vec<u8> = (0..10u8).collect();

    let mut stream = super::Encrypted::new(
        StalledWriter {
            accept: 4,
            ok_polls: 1,
            written: Vec::new(),
        },
        Some(Arc4::new(&key)),
        None,
    );

    // Stage the ciphertext remainder (partial 4/10).
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &plaintext) {
        Poll::Ready(Ok(4)) => {}
        other => panic!("expected Ok(4) partial write, got {other:?}"),
    }

    // poll_flush drains the staged ciphertext: the stalled inner writer
    // (Ok(0)) must surface as WriteZero, not spin the drain loop forever.
    match AsyncWrite::poll_flush(Pin::new(&mut stream), &mut poll_cx()) {
        Poll::Ready(Err(e)) => assert_eq!(ErrorKind::WriteZero, e.kind()),
        other => panic!("expected WriteZero, got {other:?}"),
    }
}

/// Scripted poll_write outcomes (`Accept(n)` -> Ok(n), `Stall` -> Pending).
enum Step {
    Accept(usize),
    Stall,
}

/// Inner writer driven by a script (drives the flush loop into a
/// `Pending` after unreported internal progress).
struct ScriptWriter {
    steps: std::collections::VecDeque<Step>,
    written: Vec<u8>,
}

impl AsyncWrite for ScriptWriter {
    fn poll_write(
        mut self: Pin<&mut Self>,
        _cx: &mut Context<'_>,
        buf: &[u8],
    ) -> Poll<std::io::Result<usize>> {
        match self.steps.pop_front() {
            Some(Step::Accept(n)) => {
                let n = n.min(buf.len());
                self.written.extend_from_slice(&buf[..n]);
                Poll::Ready(Ok(n))
            }
            Some(Step::Stall) => Poll::Pending,
            None => panic!("script writer steps exhausted"),
        }
    }

    fn poll_flush(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Poll::Ready(Ok(()))
    }

    fn poll_shutdown(self: Pin<&mut Self>, _cx: &mut Context<'_>) -> Poll<std::io::Result<()>> {
        Poll::Ready(Ok(()))
    }
}

/// After a `Pending` that made unreported internal progress inside the
/// flush loop, the caller's outstanding window (`staged - reported`) is
/// larger than the staged remainder: the retry with that window must be
/// accepted and drain the staged ciphertext; any other length is still
/// rejected (tokio `write_all` exercises exactly this sequence).
#[test]
fn encrypted_write_accepts_window_after_pending_internal_progress() {
    let key = [5u8; 20];
    let plaintext: Vec<u8> = (0..12u8).collect();

    let mut stream = super::Encrypted::new(
        ScriptWriter {
            steps: [
                Step::Accept(4), // call 1: first sighting, partial 4/12
                Step::Accept(4), // call 2: flush progress 4, then…
                Step::Stall,     // …Pending (unreported progress)
                Step::Accept(4), // call 3: flush completes
            ]
            .into(),
            written: Vec::new(),
        },
        Some(Arc4::new(&key)),
        None,
    );

    // First sighting: encrypt once, inner accepts 4/12 -> Ok(4).
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &plaintext) {
        Poll::Ready(Ok(4)) => {}
        other => panic!("expected Ok(4) partial write, got {other:?}"),
    }

    // Retry with the reported remainder (8): drains 4 more bytes, then
    // stalls -> Pending with unreported internal progress.
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &plaintext[4..]) {
        Poll::Pending => {}
        other => panic!("expected Pending after internal progress, got {other:?}"),
    }

    // A retry longer than the outstanding window (staged 12 - reported 4)
    // is rejected even though the staged remainder is only 4 now.
    let alien = [0xCDu8; 12];
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &alien) {
        Poll::Ready(Err(e)) => assert_eq!(ErrorKind::InvalidInput, e.kind()),
        other => panic!("expected InvalidInput, got {other:?}"),
    }

    // The correct outstanding window (8) completes the drain: the final
    // Ok reports the whole window (the unreported progress included).
    match AsyncWrite::poll_write(Pin::new(&mut stream), &mut poll_cx(), &plaintext[4..]) {
        Poll::Ready(Ok(8)) => {}
        other => panic!("expected Ok(8) window retry, got {other:?}"),
    }

    // The wire bytes are the one-shot ARC4 of the original plaintext.
    let mut expect = plaintext.clone();
    Arc4::new(&key).apply(&mut expect);
    assert_eq!(expect, stream.get_ref().written, "wire ciphertext");
}
